import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner("{n}\n{name}");
        int num = sc.nextInt();
        sc.nextLine();
        String name = sc.nextLine();
        System.out.println("数字是 " + num);
        System.out.println("名字是[" + name + "]");
    }
}
